import{_ as e,o,c as a,a as r}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const u=JSON.parse('{"title":"Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы","description":"","frontmatter":{"site":"pro","title":"Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы","date":"2026-10-01T00:00:00.000Z","source":"https://t.me/jfyi_ps/89","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-01\\"}"]]},"headers":[],"relativePath":"posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat.md","filePath":"posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat.md"}'),i={name:"posts/2026-10-01-ya-hochu-predlozhit-svoim-dorogim-chitatelyam-podumat.md"};function p(n,t,s,m,l,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<p>Я хочу предложить своим дорогим читателям подумать над решением одной сложной и дорогой проблемы. Это железо, софт и общение с поддержкой сетевого оборудования.</p><p>Однажды я собеседовался архитектором на один около-государственный проект, которым сейчас начинают пользоваться всё чаще.</p><p>Одно из требований было - обеспечить 99.99% времени доступности. И тут я отступил.</p><p>Поработав в системах с договорной доступностью 99.999%, представляю как это может быть устроено.</p><p>Большая часть крупных облачных аварий связана с сетевой частью, судя по истории инцидентов облачных провайдеров, например, Яндекс.Облака: <a href="https://status.yandex.cloud/ru/timeline" target="_blank" rel="noreferrer">https://status.yandex.cloud/ru/timeline</a>.</p><p>Мартин Клеппман в книге &quot;Высоконагруженные приложения&quot; пишет: &quot;Оказалось, что добавление избыточного сетевого оборудования не снижает частоту отказов настолько, насколько бы хотелось, поскольку не защищает от человеческого фактора (например, ошибок неправильной настройки коммутаторов) — главной причины перебоев в обслуживании.&quot;</p><p>Настроить две &quot;циски&quot;, но переплатить за серый импорт, без гарантии ИЛИ стать бета-тестером и строить сложный кластер резервирования с помощью неудобных интерфейсов (зло***чая матрёшка)?</p><p>На июнь 2026-года до 75% импортозамещения оборудования дошли только 3% необходимых компаний.</p><p>Тот же Клеппман начинает книгу с того, что удобный и понятный интерфейс обслуживания решает проблему доступности гораздо эффективнее всего остального в книге. &quot;Одно исследование показало, что основной причиной перебоев в работе были допущенные операторами ошибки в конфигурации, в то время как сбои аппаратного обеспечения (серверов или сети) играли какую-либо роль только в 10-25% случаев&quot;.</p><p>Людей, которые будут круглосуточно и оперативно решать сетевые проблемы можно пересчитать по пальцам. Они стоят дорого, и нужны пару раз в год. А людей, способных это оборудование разработать и того меньше.</p><p>Но что же мешает создавать удобные, эргономичные интерфейсы?</p><p>Когда я думал вкладываться или нет в акции БАЗИС, я посмотрел в интерфейс их систем и решил вложиться ненадолго, до первого роста, потому что когда появится конкурент с хорошим интерфейсом, эти акции быстро упадут. Вам бы вряд ли хотелось чтобы интерфейсы медицинских систем были похожи на интерфейсы БАЗИС.</p><p>Скажите, кому-нибудь удалось сделать хотя бы 98% доступности на сетевом оборудовании отечественного производства? Что можно сделать с этой фундаментальной сферой для надежности нашего будущего?</p>',13)])])}const h=e(i,[["render",p]]);export{u as __pageData,h as default};
